import {assessmentStatus} from './navigation.mjs';
// The plant reflects completed questions only; answer values never affect its mood or appearance.
export function growthState(answers){
 const {answered}=assessmentStatus(answers);
 const stage=answered===0?0:answered>=40?4:answered>=30?3:answered>=15?2:1;
 return {answered,stage,name:['Seed','Sprout','Taking root','Budding','In bloom'][stage],stem:answered===0?0:Math.min(1,.38+answered/30*.62)};
}
export function companionMarkup(){return `<aside class="growth-companion" id="growth-companion" data-growth-stage="0" aria-label="A quiet progress companion"><svg class="growth-art" id="growth-art" viewBox="0 0 160 110" role="img" aria-label="A seed. No questions answered yet."><defs><radialGradient id="growth-glow"><stop offset="0" stop-color="#c4d8b4" stop-opacity=".6"/><stop offset="1" stop-color="#edf4e5" stop-opacity="0"/></radialGradient></defs><circle class="growth-breath" cx="80" cy="57" r="49" fill="url(#growth-glow)"/><ellipse cx="80" cy="96" rx="35" ry="3" fill="#d6e1ca"/><g class="plant-sway"><ellipse class="growth-seed" cx="80" cy="87" rx="8" ry="5" fill="#b5a17d"/><path class="growth-stem" d="M80 88 C77 70 83 47 80 24" pathLength="1" fill="none" stroke="#6b8d5c" stroke-width="3" stroke-linecap="round"/><g class="growth-part leaf-one"><path d="M80 68 C60 71 48 57 52 44 C69 43 81 54 80 68Z" fill="#a6bc8d"/><path d="M59 51 80 68" stroke="#7b9966" stroke-width="1"/></g><g class="growth-part leaf-two"><path d="M81 58 C98 60 111 47 108 34 C91 33 80 45 81 58Z" fill="#7f9e6e"/><path d="M101 41 81 58" stroke="#658756" stroke-width="1"/></g><g class="growth-part leaf-three"><path d="M80 43 C66 44 58 34 62 24 C74 26 81 33 80 43Z" fill="#b7c99d"/><path d="M67 29 80 43" stroke="#8da975" stroke-width="1"/></g><g class="growth-part growth-bud"><ellipse cx="80" cy="22" rx="5" ry="7" fill="#ddc890"/></g><g class="growth-part growth-flower">${Array.from({length:6},(_,i)=>`<ellipse cx="80" cy="13" rx="5" ry="9" transform="rotate(${i*60} 80 22)" fill="#e6d5a3"/>`).join('')}<circle cx="80" cy="22" r="5.5" fill="#bda76a"/></g></g></svg><div class="companion-copy"><p class="companion-heading">Your space to grow.</p><p>One answer at a time.</p></div><button class="motion-toggle" id="motion-toggle" type="button" aria-label="Pause gentle motion" aria-pressed="false" title="Pause gentle motion">Ⅱ</button></aside>`}
